#!/usr/bin/env Rscript
# ---------------------------------------------------------------------------
# One-time seed of the race registry from the October 2026 research.
# After running this once, data/*.csv are the source of truth: edit the CSVs
# directly (or in a spreadsheet) and do NOT re-run this script, or your edits
# will be overwritten.
# ---------------------------------------------------------------------------
suppressMessages({ library(tibble); library(readr); library(dplyr) })

# Columns
#  race_id            stable slug used everywhere (sources.csv, manual_results.csv, history.csv)
#  scope              direct = squarely a data center measure; adjacent = related question;
#                     party_advisory = non-binding party primary question
#  level              municipal (city/village/town/township) | county | state
#  measure_type       charter_amendment | initiated_ordinance | zoning_referendum |
#                     zoning_adoption | advisory | referendum | land_use_authorization |
#                     direct_legislation | general_plan_amendment | board_structure
#  binding            binding | advisory
#  origin             citizen_petition | council_referred | electors_meeting | court_ordered | charter_commission
#  yes_means          restrict = YES vote is the anti-data-center side
#                     allow    = YES vote is the pro-data-center side
#  status             on_ballot | pending_litigation | decided
#  ballot_text_verbatim TRUE when ballot_text is quoted from an official source
#  poll_close_et      poll closing time in US Eastern, 24h, for the night-of timeline

races <- tribble(
  ~race_id, ~state, ~state_name, ~jurisdiction, ~jurisdiction_type, ~county, ~level, ~scope, ~election_date, ~measure_label, ~title, ~measure_type, ~binding, ~origin, ~yes_means, ~threshold_mw, ~target_project, ~proponents, ~opponents, ~summary, ~ballot_text, ~ballot_text_verbatim, ~status, ~lat, ~lon, ~ballot_text_url, ~ballotpedia_url, ~news_url, ~results_page_url, ~poll_close_et, ~result_note, ~notes,

